(40, 'Dokumen SPMI', 'Kebijakan Sistem Penjaminan Mutu Internal', '003/SPMI/2024', 2024, 'Berlaku', NULL, NULL, NULL, NULL, NULL, NULL, 'Kebijakan penjaminan mutu internal institusi', NULL, 'Indonesia', 'Kebijakan ini menetapkan arah dan strategi penjaminan mutu di Institut Teknologi dan Kesehatan Mahardika.', '[\"spmi\",\"penjaminan mutu\",\"kebijakan\",\"institusi\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/sample3', '07869125-83ae-11f0-bbf3-44e8d4ab647d', '2026-08-06 00:02:00', '2026-08-30 21:14:17', '2026-08-30 21:14:17'),
(42, 'Surat Keputusan (SK) Rektor', 'Surat Keputusan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Pengangkatan Pengelola Penjaminan Mutu Institut Teknologi Dan Kesehatan Mahardika Periode 2024 - 2028', 'Kep.027/ITEKESMA/IV/2024', 2024, 'Berlaku', '2024-04-08', '2024-04-08', NULL, 'Cirebon', 'Rektor', 'Rektorat', 'Tata Kelola / Penjaminan Mutu / Kepegawaian', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan pengangkatan pengelola Lembaga Penjaminan Mutu (LPM) ITEKES Mahardika untuk periode 2024–2028. Keputusan yang dikeluarkan oleh Rektor Dr. Yani Kamasturyani ini bertujuan menjaga efektivitas Sistem Penjaminan Mutu Internal (SPMI) serta mengisi kekosongan jabatan dengan masa bakti selama empat tahun. Struktur pengelola yang baru diangkat ini mencakup penunjukan personel untuk mengisi posisi mutu di tingkat institusi, fakultas, hingga tingkat program studi di lingkungan kampus.', '[\"#PenjaminanMutu #LPMI #SDM #TataKelola #SKRektor\"]', 28, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1FeJfUJgmQBfES2vtPQ_V7Fj9OrjvL5U_/view?usp=sharing', NULL, '2026-08-07 21:15:41', '2026-08-31 00:30:34', NULL),
(43, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Peraturan Pegawai Tetap Institut Teknologi Dan Kesehatan Mahardika', '15 TAHUN 2023', 2023, 'Berlaku', '2023-03-20', '2023-03-20', NULL, 'Cirebon', 'Rektor Institut Teknologi dan Kesehatan Mahardika', 'Rektorat', 'SDM / Kepegawaian / Tata Kelola', 'Non Akademik', 'Indonesia', 'Dokumen ini mengatur ketentuan mengenai kedudukan, kewajiban, hak, serta sistem pembinaan profesi bagi pegawai tetap yang meliputi tenaga pendidik dan tenaga kependidikan. Kebijakan di dalamnya mencakup manajemen pengadaan pegawai, penataan struktur kepangkatan dan jabatan, hingga penerapan sistem disiplin serta sanksi kerja. Selain itu, diatur pula mekanisme penilaian kinerja berkala yang transparan untuk mendasari pengembangan karier, pemberian penghargaan, maupun hak cuti pegawai.', '[\"#Kepegawaian #SDM #PeraturanRektor #TataKelola\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1mDWcMPQRkwipbRYOTZaxzkoSAx4BO-QP/view?usp=sharing', NULL, '2026-08-08 02:12:33', '2026-08-30 21:49:54', NULL),
(44, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Nota Kesepahaman / Memorandum Of Understanding (Mou)', '024 TAHUN 2023', 2023, 'Berlaku', '2023-09-18', '2023-09-18', NULL, 'Cirebon', 'Rektor Institut Teknologi dan Kesehatan Mahardika', 'Rektorat', 'Kerjasama / Hubungan Masyarakat / Tata Kelola', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan pedoman resmi mengenai penyusunan dan pelaksanaan Nota Kesepahaman (MoU) sebagai landasan awal komitmen kerja sama dengan berbagai pihak, baik dalam maupun luar negeri. Kebijakan ini bertujuan untuk menjamin kepastian hukum, tertib administrasi, serta efektivitas pengelolaan jaringan kerja sama demi mendukung perwujudan visi, misi, dan Tridharma Perguruan Tinggi. Di dalamnya diatur secara terstruktur mengenai prinsip dasar, standar muatan isi, mekanisme pengajuan, sumber pendanaan, hingga prosedur monitoring dan evaluasi secara berkala.', '[\"#Kerjasama #MoU #NotaKesepahaman #PeraturanRektor #TataKelola\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/14AJCIqs9r4hlwaMAE_v5DSa_W6s80fkN/view?usp=sharing', NULL, '2026-08-08 02:47:24', '2026-08-30 21:50:23', NULL),
(45, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Organisasi Dan Tata Kerja Antar Organ', '020 TAHUN 2023', 2023, 'Berlaku', '2023-06-13', '2023-06-13', NULL, 'Cirebon', 'Rektor Institut Teknologi dan Kesehatan Mahardika', 'Rektorat', 'Tata Kelola / Kelembagaan / SOTK', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan pedoman sistem organisasi dan mekanisme hubungan kerja antarorgan di lingkungan institut guna mewujudkan tata kelola perguruan tinggi yang baik, transparan, dan akuntabel. Peraturan tersebut memperjelas pembagian tugas serta fungsi dari organ penyelenggara, akademik, eksekutif, dan pengawas agar tercipta koordinasi yang harmonis serta efektif dalam mencapai visi-misi institusi.', '[\"#SOTK #TataKelola #Kelembagaan #PeraturanRektor\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1bdF0c1FQ-jS4TY5fO1pRbSLPuFXvjO_W/view?usp=sharing', NULL, '2026-08-08 03:03:41', '2026-08-30 21:49:27', NULL),
(46, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Organisasi Dan Tata Kerja Fakultas Dan Program Studi', '021 TAHUN 2023', 2023, 'Berlaku', '2023-06-13', '2023-06-13', NULL, 'Cirebon', 'Rektor Institut Teknologi dan Kesehatan Mahardika', 'Rektorat', 'Tata Kelola / Kelembagaan / SOTK', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan struktur organisasi, kedudukan, tugas pokok, serta fungsi dari setiap unit di tingkat fakultas dan program studi sebagai pedoman penyelenggaraan kegiatan akademik dan administrasi. Peraturan tersebut juga mengatur tata kerja dan pola koordinasi antar-pimpinan, dosen, tenaga kependidikan, serta lembaga penjaminan mutu di lingkungan institut guna menjamin tata kelola yang efektif dan akuntabel.', '[\"#SOTK #Fakultas #ProgramStudi #TataKelola #Kelembagaan #PeraturanRektor\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1sk2TrOjOyKvr-vS3kgBh8RXBl2O0OVkF/view?usp=sharing', NULL, '2026-08-08 03:10:53', '2026-08-30 21:49:08', NULL),
(47, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Organisasi Dan Tata Kerja Komite Audit (KA)', '012 TAHUN 2023', 2023, 'Berlaku', '2023-08-12', '2023-08-12', NULL, 'Cirebon', 'Rektor Institut Teknologi dan Kesehatan Mahardika', 'Rektorat', 'Tata Kelola / Kelembagaan / SOTK', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan pembentukan, fungsi, tugas, dan tanggung jawab Komite Audit sebagai organ pendukung Senat Akademik yang bersifat independen dan profesional dalam mengawasi sistem pengendalian internal serta manajemen risiko di lingkungan institut. Di dalamnya juga diatur ketentuan mengenai keanggotaan, tata cara rapat, hubungan kerja, mekanisme pelaporan berkala, hingga aspek pendanaan dan penegakan kode etik bagi para anggotanya.', '[\"#SOTK #KomiteAudit #TataKelola #Kelembagaan #PeraturanRektor\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1u5JlsvLVn9Oh1DuiqngXci7Z_0mSy2AZ/view?usp=sharing', NULL, '2026-08-08 03:17:58', '2026-08-30 21:48:35', NULL),
(48, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Pengembangan Sumber Daya Manusia', '20 TAHUN 2023', 2023, 'Berlaku', '2023-04-30', '2023-04-30', NULL, 'Cirebon', 'Rektor Institut Teknologi dan Kesehatan Mahardika', 'Rektorat', 'SDM / Kepegawaian / Pengembangan Karir', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan tata kelola, acuan perencanaan, pelaksanaan, serta evaluasi dalam pengembangan sumber daya manusia secara sistematis untuk menjamin penyelenggaraan pendidikan tinggi yang profesional. Di dalamnya diatur ketentuan mengenai peningkatan kompetensi, kualifikasi akademik, pengembangan karier, standar kerja, hingga mekanisme pemberian penghargaan dan sanksi bagi dosen serta tenaga kependidikan.', '[\"#PengembanganSDM #SDM #Kepegawaian #Pelatihan #PeraturanRektor\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1uLQlcunpfa9ALPIdCsVUuPUQAtYHPSwG/view?usp=sharing', NULL, '2026-08-08 03:48:50', '2026-08-30 21:48:11', NULL),
(49, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Penyelenggaraan Pembelajaran Program Merdeka Belajar Kampus Merdeka (MBKM) Di Institut Teknologi Dan Kesehatan Mahardika', '13 TAHUN 2023', 2023, 'Berlaku', '2023-06-20', '2023-06-20', NULL, 'Cirebon', 'Rektor', 'Rektorat', 'Kurikulum / Pembelajaran / MBKM', 'Akademik', 'Indonesia', 'Dokumen ini mengatur tentang ketentuan dan mekanisme pelaksanaan program Merdeka Belajar Kampus Merdeka (MBKM) bagi mahasiswa program Sarjana (S1). Di dalamnya dimuat panduan mengenai bentuk kegiatan pembelajaran di luar kampus, proses konversi nilai dan SKS, penjaminan mutu, hingga prosedur operasional pelaporan hasil belajar mahasiswa.', '[\"#MBKM #Pembelajaran #Kurikulum #Akademik #PeraturanRektor #MerdekaBelajar\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1Uibv6x6u_VNSvK9ZDo8VyT0bsiR-C8Cs/view?usp=sharing', NULL, '2026-08-09 08:21:42', '2026-08-30 21:43:31', NULL),
(50, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Unsur Pelaksana Pengawasan Internal', '025 TAHUN 2023', 2023, 'Berlaku', '2023-06-20', '2023-06-20', NULL, 'Cirebon', 'Rektor', 'Rektorat', 'Tata Kelola / Kelembagaan / Pengawasan Internal', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan pembentukan, kedudukan, tugas, dan fungsi Satuan Pengawas Internal (SPI) sebagai unit kerja yang bertanggung jawab langsung kepada Rektor untuk menjalankan pengawasan non-akademik. Ruang lingkup kerjanya mencakup pengawasan, reviu, serta monitoring terhadap bidang keuangan, aset, sumber daya manusia, tata kelola, pengadaan barang, dan manajemen risiko di seluruh unit kerja perguruan tinggi.', '[\"#PengawasanInternal #TataKelola #Kelembagaan #PeraturanRektor #AuditInternal\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1U66CL2-Yc6dor37NU0w7pezXRQVTOtE3/view?usp=sharing', NULL, '2026-08-09 08:25:30', '2026-08-30 21:43:16', NULL),
(51, 'Surat Keputusan (SK) Rektor', 'Surat Keputusan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Penetapan Visi, Misi, Tujuan Dan Sasaran Institut Teknologi Dan Kesehatan Mahardika', 'Kep.005/ITEKESMA/II/2023', 2023, 'Berlaku', '2023-02-06', '2023-02-06', NULL, 'Cirebon', 'Rektor Institut Teknologi dan Kesehatan Mahardika', 'Rektorat', 'Tata Kelola / Perencanaan Stratejis / VMTS', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan visi, misi, tujuan, dan sasaran institusi yang berfokus pada penyelenggaraan Tri Dharma Perguruan Tinggi secara profesional, berkualitas, serta berdaya saing global hingga tahun 2043. Keputusan ini menjadi dasar hukum pelaksanaan tata kelola dan pengembangan mutu akademik bagi seluruh fakultas serta program studi yang bernaung di bawah institusi tersebut.', '[\"#VMTS #VisiMisi #RencanaStrategis #TataKelola #SKRektor #Kelembagaan\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1T2atC7jJRLdzJvjN5jO7B5WoRLDt0Eej/view?usp=sharing', NULL, '2026-08-09 08:31:32', '2026-09-10 19:32:16', NULL),
(52, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Pedoman Penyusunan Kurikulum Outcome Based Education (OBE)', 'PER. 25 TAHUN 2024', 2024, 'Berlaku', '2024-03-20', '2024-03-20', NULL, 'Cirebon', 'Rektor', 'Rektorat', 'Kurikulum / Pembelajaran / Penjaminan Mutu Akademik', 'Akademik', 'Indonesia', 'Peraturan ini diterbitkan untuk menetapkan pedoman dalam menyusun kurikulum pendidikan tinggi yang terstruktur serta berorientasi pada perkembangan masyarakat melalui pendekatan Outcome Based Education (OBE). Di dalamnya diatur ketentuan umum mengenai organ kampus serta tahapan penyusunan kurikulum oleh Dekan dan tim penyusun, yang wajib melalui proses pertimbangan Senat Akademik Fakultas serta reviu oleh Lembaga Pengembangan Pendidikan.', '[\"#KurikulumOBE #OBE #Kurikulum #Akademik #PeraturanRektor #PedomanPenyusunan\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1mPFwZbFN7vAnynfJtM5an5DoopCvC5qo/view?usp=sharing', NULL, '2026-08-09 08:37:23', '2026-08-30 21:42:20', NULL),
(53, 'Pedoman dan Panduan', 'Pedoman Penyusunan Kurikulum Outcome Based Education (OBE)', 'PER. 25 TAHUN 2024', 2024, 'Berlaku', '2024-06-20', '2024-06-20', NULL, 'Cirebon', 'Rektor', 'Rektorat', 'Kurikulum / Pembelajaran / Penjaminan Mutu Akademik', 'Akademik', 'Indonesia', 'Pedoman ini memuat format penyusunan kurikulum program studi yang mencakup rumusan visi misi, evaluasi kurikulum, capaian pembelajaran berdasarkan prinsip S.M.A.R.T, serta penetapan bahan kajian dan rekonstruksi mata kuliah. Selain itu, dokumen ini juga mengatur struktur kurikulum lintas semester, penyusunan Rencana Pembelajaran Semester (RPS), hingga sistem manajemen serta penjaminan mutu implementasi kurikulum.', '[\"#KurikulumOBE #OBE #Kurikulum #Akademik #PeraturanRektor #PedomanPenyusunan\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1mPFwZbFN7vAnynfJtM5an5DoopCvC5qo/view?usp=sharing', NULL, '2026-08-09 08:44:15', '2026-08-31 21:04:10', NULL),
(54, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Tata Nilai, Budaya Kerja, Dan Kode Etik Pegawai', 'PER. 24 TAHUN 2024', 2024, 'Berlaku', '2024-04-20', '2024-04-20', NULL, 'Cirebon', 'Rektor', 'Rektorat', 'SDM / Kepegawaian / Tata Kelola', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan panduan bersikap, berperilaku, dan bertindak yang mencakup tata nilai sinergi, integritas, inovatif, akuntabel, dan profesional bagi pegawai di lingkungan institusi. Peraturan ini juga memuat kode etik komprehensif, tata cara penegakan melalui komite ad hoc, serta sanksi bagi pelanggar guna mewujudkan etos kerja yang bersih, bertanggung jawab, dan berintegritas.', '[\"#KodeEtik #BudayaKerja #TataNilai #SDM #Kepegawaian #PeraturanRektor\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1RTUcLeujfwYilOFkqbEa8izC9-3_6dgq/view?usp=sharing', NULL, '2026-08-09 08:53:01', '2026-08-30 21:41:11', NULL),
(55, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Peta Proses Bisnis Dan Standar Operasional Prosedur', 'PER.01 TAHUN 2024', 2024, 'Berlaku', '2024-01-18', '2024-01-18', NULL, 'Cirebon', 'Rektor', 'Rektorat', 'Tata Kelola / Manajemen Operasional / Sistem Informasi & Prosedur', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan acuan resmi bagi seluruh unit kerja perguruan tinggi dalam melaksanakan dan mengevaluasi peta proses bisnis serta standar prosedur operasional (SPO) sesuai tugas masing-masing. Penerapan regulasi ini mencakup klasifikasi layanan inti, layanan pendukung, dan layanan lainnya guna meningkatkan efektivitas, efisiensi, produktivitas, serta pelayanan profesional kepada para pemangku kepentingan.', '[\"#ProsesBisnis #SOP #TataKelola #ManajemenOperasional #PeraturanRektor #PetaProses\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1rY936V45TE458B4rjw9QjDzC_jhJOlQZ/view?usp=sharing', NULL, '2026-08-09 08:58:20', '2026-08-30 21:36:13', NULL),
(56, 'Surat Keputusan (SK) Dekan', 'Surat Keputusan Dekan Fakultas Kesehatan Institut Teknologi Dan Kesehatan Mahardika Tentang Pemberlakuan Pedoman Penilaian Mahasiswa Program Studi Pendidikan Profesi Ners Fakultas Kesehatan', 'Kep.060/ITEKESMA.FK/VII/2024', 2024, 'Berlaku', '2024-06-16', '2024-06-16', NULL, 'Cirebon', 'Dekan Fakultas Kesehatan Institut Teknologi Dan Kesehatan Mahardika', 'Fakultas', 'Penilaian Akademik / Kurikulum & Pembelajaran / Profesi Ners', 'Akademik', 'Indonesia', 'Dokumen ini menetapkan pemberlakuan pedoman penilaian hasil belajar bagi mahasiswa Program Studi Pendidikan Profesi Ners untuk memastikan sistem evaluasi yang objektif, akuntabel, dan berbasis Outcome-Based Education (OBE). Pedoman ini menjadi acuan wajib dalam pelaksanaan serta pelaporan evaluasi belajar pada tahap akademik maupun klinik, dengan pengawasan berkala oleh unit penjaminan mutu.', '[\"#PenilaianMahasiswa #ProfesiNers #FakultasKesehatan #PedomanPenilaian #Akademik #SKDekan\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/15hr28lZiiCtA_GPud7QSI3rdwkwlI2Pm/view?usp=sharing', NULL, '2026-08-09 09:04:40', '2026-08-31 00:30:05', NULL),
(57, 'Surat Keputusan (SK) Rektor', 'Surat Keputusan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Perubahan Atas Keputusan Rektor Institut Teknologi Dan Kesehatan Mahardika Nomor Kep.007/ITEKESMA/II/2023 Tentang Struktur Organisasi', 'Kep.027/ITEKESMA/II/2025', 2025, 'Berlaku', '2025-02-19', '2025-02-19', NULL, 'Cirebon', 'Rektor Institut Teknologi dan Kesehatan Mahardika', 'Rektorat', 'Tata Kelola / Kelembagaan / SOTK', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan perubahan struktur organisasi perguruan tinggi melalui restrukturisasi guna mengakomodasi fungsi pengawasan standar kesehatan, keselamatan kerja, dan pengelolaan lingkungan. Melalui penyesuaian ini, dibentuk unit kerja baru bernama Kesehatan dan Keselamatan Kerja serta Lingkungan (K3L) sebagai unit pelaksana teknis untuk menjamin terciptanya lingkungan kampus yang aman, sehat, dan berkelanjutan.', '[\"#SOTK #StrukturOrganisasi #PerubahanSK #TataKelola #Kelembagaan #SKRektor\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1EZrFqua8gIFKQaXuRu6AZAFCFfOz8Hx8/view?usp=sharing', NULL, '2026-08-09 09:11:20', '2026-08-31 00:29:26', NULL),
(58, 'Peraturan Rektor', 'Peraturan Rektor Institut Teknologi Dan Kesehatan Mahardika Tentang Pedoman Penyelenggaraan Pendidikan', 'PER. 46 TAHUN 2025', 2025, 'Berlaku', '2025-06-20', '2025-06-20', NULL, 'Cirebon', 'Rektor', 'Rektorat', 'Pembelajaran / Tata Kelola Akademik / Pedoman Pendidikan', 'Akademik', 'Indonesia', 'Dokumen ini menetapkan pedoman tata kelola penyelenggaraan pendidikan di perguruan tinggi guna menjamin transparansi, akuntabilitas, serta keadilan akademik dan administratif bagi seluruh sivitas akademika. Di dalamnya diatur ketentuan mengenai sistem pembelajaran, beban belajar mahasiswa, pelaksanaan kurikulum berbasis kompetensi, hingga mekanisme evaluasi serta pemenuhan syarat kelulusan tingkat akhir.', '[\"#PedomanPendidikan #PenyelenggaraanPendidikan #Akademik #PeraturanRektor #TataKelolaAkademik\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1xUwsFOWvrcgDS9DuQiZiBQZjoSUwSoea/view?usp=sharing', NULL, '2026-08-09 09:17:13', '2026-08-30 21:35:53', NULL),
(59, 'Keputusan Lainnya', 'Keputusan Menteri Pendidikan Tinggi, Sains, Dan Teknologi Republik Indonesia Tentang Izin Perubahan Bentuk Institut Teknologi Dan Kesehatan Mahardika Di Kota Cirebon Menjadi Universitas Insan Mahardika Di Kota Cirebon Provinsi Jawa Barat Yang Diselenggarakan Oleh Yayasan Pengembangan Ilmu Mahardika', '623/B/O/2026', 2026, 'Berlaku', '2026-06-12', '2026-06-12', NULL, 'Jakarta', 'DIRJEN DIKTI', 'Ditjen Dikti', 'Tata Kelola / Kelembagaan / Legalitas PT', 'Akademik', 'Indonesia', 'Surat Keputusan ini menetapkan izin resmi perubahan bentuk institusi pendidikan dari tingkat institut menjadi universitas. Melalui perubahan ini, universitas diwajibkan menyelenggarakan berbagai program studi pilihan serta memenuhi seluruh standar nasional pendidikan tinggi dan sistem penjaminan mutu yang berlaku.', '[\"#PerubahanBentuk #UniversitasInsanMahardika #KeputusanMenteri #Kemendiktisainstek #Legalitas #Kelembagaan\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1T1yAkgNtay2qEV2a-kIqS4XBBF_Qcr_-/view?usp=sharing', NULL, '2026-08-09 20:22:40', '2026-08-30 22:35:47', NULL);
INSERT INTO `documents` (`id`, `tipe_dokumen`, `judul`, `nomor`, `tahun`, `status`, `tanggal_penetapan`, `tanggal_pengundangan`, `tanggal_berakhir`, `tempat_penetapan`, `penandatangan`, `sumber`, `subjek`, `bidang`, `bahasa`, `ringkasan`, `tags`, `mencabut_id`, `dicabut_dengan_id`, `mencabut_teks`, `dicabut_dengan_teks`, `file_url`, `gdrive_url`, `legacy_source_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(60, 'Peraturan Rektor', 'Peraturan Rektor Universitas Insan Mahardika Tentang Kebijakan Sistem Penjaminan Mutu Internal (SPMI)', '007 TAHUN 2026', 2026, 'Berlaku', '2026-08-02', '2026-08-02', NULL, 'Cirebon', 'Rektor', 'Rektorat', 'Penjaminan Mutu / SPMI / Kebijakan Mutu', 'Akademik', 'Indonesia', 'Dokumen ini memuat regulasi mengenai kerangka kerja penjaminan mutu internal yang fleksibel, adaptif, berbasis luaran (OBE), dan terintegrasi secara digital untuk membangun budaya mutu secara mandiri dan berkelanjutan. Kebijakan ini mencakup ruang lingkup dokumen mutu, manajemen siklus PPEPP, pengelolaan data berbasis sistem informasi, serta integrasi data dengan penjaminan mutu eksternal.', '[\"#SPMI #KebijakanSPMI #PenjaminanMutu #LPMI #PeraturanRektor #UniversitasInsanMahardika\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1vCdyPT1za74KZpNe2F9vxvVGIIhjGF3i/view?usp=sharing', NULL, '2026-08-10 21:25:47', '2026-08-30 21:35:03', NULL),
(61, 'Peraturan Rektor', 'Peraturan Rektor Universitas Insan Mahardika Tentang Pengelolaan Sistem Penjaminan Mutu Internal', '009 TAHUN 2026', 2026, 'Berlaku', '2026-08-04', '2026-08-04', NULL, 'Cirebon', 'Rektor', 'Rektorat', 'Penjaminan Mutu / SPMI / Tata Kelola Mutu', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan pedoman sistematis pengelolaan penjaminan mutu internal secara otonom dan berkelanjutan melalui siklus Penetapan, Pelaksanaan, Evaluasi, Pengendalian, dan Peningkatan (PPEPP). Peraturan ini juga mengintegrasikan sistem informasi digital yang terhubung secara real-time untuk mendukung pengambilan keputusan berbasis data serta memfasilitasi kurikulum yang adaptif dan fleksibel', '[\"#SPMI\",\"#PengelolaanSPMI\",\"#PenjaminanMutu\",\"#LPPPMI\",\"#PeraturanRektor\",\"#UniversitasInsanMahardika\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/16MBeyg-QygmE-eE2K-bmDrf567LfMwdm/view?usp=sharing', NULL, '2026-08-10 21:30:36', '2026-08-30 21:34:53', NULL),
(62, 'Dokumen SPMI', 'Standar SPMI Tahun 2023', 'STD/SPMI/LPM-ITEKESMA/2023', 2023, 'Tidak Berlaku', '2023-06-26', '2023-07-03', NULL, 'Cirebon', 'Rektor', 'LPMI', 'Penjaminan Mutu / SPMI', 'Non Akademik', 'Indonesia', 'Dokumen ini memuat standar penjaminan mutu internal yang disusun sebagai panduan strategis dan operasional untuk mengendalikan serta meningkatkan kualitas penyelenggaraan pendidikan tinggi. Di dalamnya mencakup regulasi menyeluruh yang mengatur aspek pembelajaran, penelitian, pengabdian kepada masyarakat, hingga tata kelola SDM, sarana prasarana, dan pembiayaan institusi', '[\"#StandarSPMI #SPMI #StandarAkademik #StandarNonAkademik #PenjaminanMutu #LPMI #DokumenSPMI\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1FgBXtNNdRt3R7aUWqHUpMdowSTCsOT9b/view?usp=sharing', NULL, '2026-08-19 04:51:17', '2026-08-19 04:57:31', NULL),
(63, 'Dokumen SPMI', 'Standar SPMI Tahun 2024', 'STD/SPMI/LPM-ITEKESMA/2024', 2024, 'Berlaku', '2024-02-06', '2024-02-06', NULL, 'Cirebon', 'Rektor', 'LPMI', 'Penjaminan Mutu / SPMI', 'Non Akademik', 'Indonesia', 'Dokumen ini menetapkan standar mutu penjaminan internal yang mencakup aspek pendidikan, penelitian, dan pengabdian kepada masyarakat demi mewujudkan penjaminan mutu yang bertahap dan berkelanjutan. Seluruh kriteria di dalamnya digunakan sebagai acuan wajib bagi institut, fakultas, program studi, hingga unit kerja dalam menyelenggarakan tata kelola pendidikan tinggi yang akuntabel dan berdaya saing global.', '[\"#StandarSPMI #SPMI #StandarAkademik #StandarNonAkademik #PenjaminanMutu #LPMI #StandarMutu2024 #DokumenSPMI\"]', 62, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1XFwWC3PCr1WhYW9-pNMF2XP_MCzOAxx0/view?usp=sharing', NULL, '2026-08-19 04:57:11', '2026-08-19 04:57:11', NULL),
(64, 'Dokumen SPMI', 'Kebijakan SPMI Tahun 2024', 'KEB/SPMI/LPM-ITEKESMA/I', 2024, 'Berlaku', '2024-06-15', '2024-06-15', NULL, 'Cirebon', 'Rektor', 'LPMI', 'Penjaminan Mutu / SPMI / Kebijakan Mutu', 'Non Akademik', 'Indonesia', 'Dokumen ini memuat panduan komprehensif mengenai Sistem Penjaminan Mutu Internal (SPMI) perguruan tinggi yang dirancang untuk mengintegrasikan standar nasional pendidikan tinggi guna membangun budaya mutu berkelanjutan. Kebijakan ini mencakup manajemen dengan siklus PPEPP, sasaran strategis, struktur organisasi penjaminan mutu, serta daftar standar mutu akademik dan non-akademik yang menjadi acuan pokok pelaksanaan Tri Dharma Perguruan Tinggi.', '[\"#KebijakanSPMI #SPMI #KebijakanMutu #PenjaminanMutu #LPMI #DokumenSPMI #SPMI2024\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1EhnbUI044SvjblnhbGqKbLBwml1ffFNd/view?usp=sharing', NULL, '2026-08-19 05:05:11', '2026-08-19 05:05:11', NULL),
(65, 'Dokumen SPMI', 'Manual SPMI Tahun 2023', 'MAN/SPMI/LPM-ITEKESMA/2023', 2023, 'Berlaku', '2023-06-26', '2023-06-26', NULL, 'Cirebon', 'Rektor', 'LPMI', 'Penjaminan Mutu / SPMI / Manual Mutu', 'Non Akademik', 'Indonesia', 'Dokumen ini merupakan panduan praktis mengenai petunjuk dan prosedur sistematis dalam menetapkan, melaksanakan, mengevaluasi, mengendalikan, serta meningkatkan standar mutu perguruan tinggi secara berkelanjutan. Implementasi panduan ini mencakup bidang akademik maupun non-akademik guna mewujudkan budaya mutu dan mendukung tercapainya visi misi institusi.', '[\"#ManualSPMI #SPMI #ManualMutu #PenjaminanMutu #LPMI #DokumenSPMI #SPMI2023\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/1kwVY4OXyso90TEEVF_m5WxetMwbR2MEr/view?usp=sharing', NULL, '2026-08-19 05:10:11', '2026-08-19 05:10:11', NULL),
(66, 'Dokumen SPMI', 'Manual SPMI Tahun 2024', 'MAN/SPMI/LPM-ITEKESMA/2024', 2024, 'Berlaku', '2024-06-26', '2024-06-26', NULL, 'Cirebon', 'Rektor', 'LPMI', 'Penjaminan Mutu / SPMI / Manual Mutu', 'Non Akademik', 'Indonesia', 'Dokumen ini merupakan panduan operasional dalam melaksanakan, mengevaluasi, mengendalikan, dan meningkatkan penjaminan mutu di lingkungan Institut Teknologi dan Kesehatan Mahardika secara berkelanjutan. Isinya mencakup berbagai manual standar mutu yang terbagi ke dalam kelompok utama pendidikan, penelitian, pengabdian kepada masyarakat, serta standar mutu tambahan perguruan tinggi.', '[\"#ManualSPMI #SPMI #ManualMutu #PenjaminanMutu #LPMI #DokumenSPMI #SPMI2024\"]', 65, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/13q4IZk36zaQtun57oMi4AKYbR2LxwbLU/view?usp=sharing', NULL, '2026-08-19 05:13:31', '2026-08-19 05:13:31', NULL),
(67, 'Dokumen SPMI', 'Formulir SPMI Tahun 2023', 'Dok.Form/SPMI/2023', 2023, 'Berlaku', '2023-03-20', '2023-03-20', NULL, 'Cirebon', 'Rektor', 'LPMI', 'Penjaminan Mutu / SPMI / Formulir & Instrumen Mutu', 'Non Akademik', 'Indonesia', 'Dokumen ini berisi kumpulan formulir Sistem Penjaminan Mutu Internal (SPMI) yang digunakan untuk mengevaluasi dan memonitor berbagai standar mutu pendidikan di institusi. Di dalamnya mencakup instrumen kuesioner kepuasan bagi mahasiswa, dosen, mitra, dan pegawai, kriteria evaluasi kinerja dosen, serta lembar audit untuk memantau pemenuhan standar akademik dan non-akademik.', '[\"#FormulirSPMI #SPMI #FormulirMutu #InstrumenSPMI #PenjaminanMutu #LPMI #DokumenSPMI #SPMI2023\"]', NULL, NULL, NULL, NULL, NULL, 'https://drive.google.com/file/d/11_oKbgZtLGVrCYunWagB2pzbJ5INwD9q/view?usp=sharing', NULL, '2026-08-19 06:10:53', '2026-09-13 07:43:36', NULL),
